<?php
function fixtureRemote(string $dir):\Okp\Update\Remote {$m=json_decode(file_get_contents($dir.'/update-manifest.json'),true);$id=str_repeat('a',64);$base='https://app.52okp.com/api/v1/projects/open52okp/releases/'.$id;$r=['format'=>1,'id'=>$id,'project'=>'open52okp','product'=>'open52okp','channel'=>'stable','status'=>'published','verification'=>'github-sha256','version'=>$m['version'],'from'=>$m['from'],'notes'=>$m['notes'],'size'=>filesize($dir.'/open52okp-update.zip'),'sha256'=>hash_file('sha256',$dir.'/open52okp-update.zip'),'download_url'=>$base.'/package','manifest_url'=>$base.'/manifest'];foreach(['open52okp-update.zip'=>'package','update-manifest.json'=>'manifest'] as $file=>$part)$r['assets'][$file]=['size'=>filesize($dir.'/'.$file),'sha256'=>hash_file('sha256',$dir.'/'.$file),'url'=>$base.'/'.$part];return new \Okp\Update\Remote('open52okp',str_repeat('b',64),function($url,$dest)use($dir,$r){$body=str_ends_with($url,'/manifest')?file_get_contents($dir.'/update-manifest.json'):(str_ends_with($url,'/package')?file_get_contents($dir.'/open52okp-update.zip'):json_encode($r));file_put_contents($dest,$body);});}
